def _authoring_evidence_requirement(item: dict[str, Any]) -> str:
    """Return the V30 evidence contract while preserving older workflow behavior."""

    requirement = str(item.get("evidence_requirement") or "").strip().casefold()
    if requirement in _AUTHORING_EVIDENCE_REQUIREMENTS:
        return requirement
    return "required" if bool(item.get("requires_research")) else "none"


def _requires_verified_external_evidence(item: dict[str, Any]) -> bool:
    return _authoring_evidence_requirement(item) == "required"


